// jsdom doesn't expose Text{En,De}coder.
import { TextDecoder, TextEncoder } from 'node:util';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { ZimReader } from '../ZimReader';

global.TextDecoder = global.TextDecoder || TextDecoder;
global.TextEncoder = global.TextEncoder || TextEncoder;

const COMPRESSION_NONE = 1;
const HEADER_CLUSTER_COUNT_OFFSET = 28;

// Generated by build_minimal_zim() in kolibri/plugins/zim_viewer/test/fixtures.py.
const MINIMAL_ZIM_PATH = resolve(__dirname, '../../../../test/data/minimal.zim');
function loadMinimalZim() {
  return new Uint8Array(readFileSync(MINIMAL_ZIM_PATH));
}

const descriptor = {
  clusterNumber: 0,
  blobNumber: 0,
  mimetype: 'text/html',
  namespace: 'C',
};

function resolver({ resolvable = null, onPaths = null } = {}) {
  return async paths => {
    if (onPaths) onPaths(paths);
    const results = {};
    for (const p of paths) {
      if (!resolvable || resolvable.includes(p)) results[p] = descriptor;
    }
    return results;
  };
}

function makeReader(resolveBatch = resolver()) {
  return new ZimReader('/file.zim', { resolveBatch });
}

let respond;
let xhrCalls;

class MockXHR {
  open(method, url) {
    this.method = method;
    this.url = url;
    this.requestHeaders = {};
    this._cbs = {};
  }
  setRequestHeader(name, value) {
    this.requestHeaders[name] = value;
  }
  addEventListener(type, cb) {
    (this._cbs[type] || (this._cbs[type] = [])).push(cb);
  }
  getResponseHeader(name) {
    const headers = this._res.headers || {};
    const key = Object.keys(headers).find(k => k.toLowerCase() === name.toLowerCase());
    return key === undefined ? null : headers[key];
  }
  _fire(type) {
    (this._cbs[type] || []).forEach(cb => cb());
  }
  send() {
    const req = { url: this.url, headers: this.requestHeaders, responseType: this.responseType };
    xhrCalls.push(req);
    this._res = respond(req);
    this.status = this._res.status;
    this.response = this._res.response;
    this._aborted = false;
    this.readyState = MockXHR.HEADERS_RECEIVED;
    this._fire('readystatechange');
    if (this._aborted) {
      this._fire('abort');
      return;
    }
    this._fire('load');
  }
  abort() {
    this._aborted = true;
  }
}
MockXHR.HEADERS_RECEIVED = 2;

function installXHR() {
  respond = () => ({ status: 200, headers: {}, response: null });
  xhrCalls = [];
  global.XMLHttpRequest = MockXHR;
}
function uninstallXHR() {
  delete global.XMLHttpRequest;
}

function rangeSlice(fileBytes, rangeHeader) {
  const m = /^bytes=(\d+)-(\d+)$/.exec(rangeHeader);
  return fileBytes.slice(Number(m[1]), Number(m[2]) + 1).buffer;
}

function storage(fileBytes, { advertiseMax = null } = {}) {
  return ({ headers }) => {
    const respHeaders = advertiseMax ? { 'X-Accept-Ranges-Max': String(advertiseMax) } : {};
    return { status: 206, headers: respHeaders, response: rangeSlice(fileBytes, headers.Range) };
  };
}

describe('ZimReader', () => {
  let fileBytes;
  beforeEach(() => {
    installXHR();
    fileBytes = loadMinimalZim();
  });
  afterEach(uninstallXHR);

  it('init() populates header and clusterPointers', async () => {
    respond = ({ headers }) => ({
      status: 206,
      headers: {},
      response: rangeSlice(fileBytes, headers.Range),
    });
    const reader = makeReader();
    await reader.init();
    expect(reader.header.articleCount).toBe(1);
    expect(reader.header.clusterCount).toBe(1);
    expect(reader.clusterPointers).toHaveLength(1);
    for (const call of xhrCalls) {
      expect(call.url).toBe('/file.zim');
      expect(call.headers.Range).toMatch(/^bytes=\d+-\d+$/);
      expect(call.responseType).toBe('arraybuffer');
    }
  });

  it('rejects a header whose cluster pointer table runs past the file', async () => {
    const bytes = loadMinimalZim();
    new DataView(bytes.buffer).setUint32(HEADER_CLUSTER_COUNT_OFFSET, 1e6, true);
    respond = ({ headers }) => ({
      status: 206,
      headers: {},
      response: rangeSlice(bytes, headers.Range),
    });
    const reader = makeReader();
    await expect(reader.init()).rejects.toThrow(/cluster pointer table/i);
    expect(xhrCalls).toHaveLength(1);
  });

  it('init() rejects a server that ignores Range, before downloading the body', async () => {
    respond = () => ({ status: 200, headers: {}, response: fileBytes.buffer });
    const abort = jest.spyOn(MockXHR.prototype, 'abort');
    const reader = makeReader();
    await expect(reader.init()).rejects.toMatchObject({ name: 'ResolveError', status: 200 });
    expect(abort).toHaveBeenCalled();
    abort.mockRestore();
  });

  it('getEntry returns the article body for C/Index', async () => {
    respond = storage(fileBytes);
    const reader = makeReader();
    await reader.init();
    const entry = await reader.getEntry('C/Index');
    expect(entry.mimetype).toBe('text/html');
    expect(entry.namespace).toBe('C');
    const text = new TextDecoder('utf-8').decode(entry.data);
    expect(text).toBe('<html><body>Hello, ZIM</body></html>');
  });

  it('getEntry issues a single resolver round trip (server resolves redirects)', async () => {
    let resolverCalls = 0;
    respond = storage(fileBytes);
    const reader = makeReader(resolver({ onPaths: () => (resolverCalls += 1) }));
    await reader.init();
    const entry = await reader.getEntry('C/Redirect');
    expect(entry.mimetype).toBe('text/html');
    expect(resolverCalls).toBe(1);
  });

  it('getEntries resolves N paths, deduplicated, in a single batch', async () => {
    let batchCalls = 0;
    let batchPaths = [];
    respond = storage(fileBytes);
    const reader = makeReader(
      resolver({
        onPaths: paths => {
          batchCalls += 1;
          batchPaths = paths;
        },
      }),
    );
    await reader.init();
    const entries = await reader.getEntries(['C/Other', 'C/Index', 'C/Other']);
    expect(batchCalls).toBe(1);
    expect(batchPaths).toEqual(['C/Other', 'C/Index']);
    expect(entries.size).toBe(2);
    expect(entries.get('C/Index').mimetype).toBe('text/html');
  });

  it('getEntries omits paths the server reported as missing', async () => {
    respond = storage(fileBytes);
    const reader = makeReader(resolver({ resolvable: ['C/Index'] }));
    await reader.init();
    const entries = await reader.getEntries(['C/Index', 'C/Missing']);
    expect(entries.has('C/Index')).toBe(true);
    expect(entries.has('C/Missing')).toBe(false);
  });

  it('getEntry throws ResolveError when the server omits the requested path', async () => {
    respond = storage(fileBytes);
    const reader = makeReader(resolver({ resolvable: [] }));
    await reader.init();
    await expect(reader.getEntry('C/Missing')).rejects.toMatchObject({
      name: 'ResolveError',
      status: 404,
    });
  });
});

describe('ZimReader multi-range fetching', () => {
  beforeEach(installXHR);
  afterEach(uninstallXHR);

  function multiClusterReader() {
    const reader = makeReader();
    reader.clusterPointers = [0, 10, 20, 30, 40];
    reader.header = { checksumPos: 50 };
    return reader;
  }

  function multipartResponder() {
    return ({ headers }) => {
      const specs = headers.Range.replace('bytes=', '').split(',');
      const boundary = 'TESTBOUNDARY';
      const chunks = [];
      for (const spec of specs) {
        const [start, end] = spec.split('-').map(Number);
        const data = new Uint8Array(end - start + 1);
        data[0] = COMPRESSION_NONE;
        chunks.push(
          new TextEncoder().encode(
            `--${boundary}\r\nContent-Type: application/octet-stream\r\n` +
              `Content-Range: bytes ${start}-${end}/50\r\n\r\n`,
          ),
        );
        chunks.push(data);
        chunks.push(new TextEncoder().encode('\r\n'));
      }
      chunks.push(new TextEncoder().encode(`--${boundary}--\r\n`));
      const total = chunks.reduce((n, c) => n + c.length, 0);
      const body = new Uint8Array(total);
      let off = 0;
      for (const c of chunks) {
        body.set(c, off);
        off += c.length;
      }
      return {
        status: 206,
        headers: { 'Content-Type': `multipart/byteranges; boundary=${boundary}` },
        response: body.buffer,
      };
    };
  }

  function multiRangeCalls() {
    return xhrCalls.filter(c => (c.headers.Range || '').includes(','));
  }

  it('refetches only the least recently used cluster once past the cache byte budget', async () => {
    respond = ({ headers }) => {
      const [start, end] = headers.Range.replace('bytes=', '').split('-').map(Number);
      const data = new Uint8Array(end - start + 1);
      data[0] = COMPRESSION_NONE;
      return { status: 206, headers: {}, response: data.buffer };
    };
    const reader = new ZimReader('/file.zim', { resolveBatch: resolver(), cacheMaxBytes: 20 });
    reader.clusterPointers = [0, 10, 20, 30, 40];
    reader.header = { checksumPos: 50 };

    await reader._getCluster(0);
    await reader._getCluster(1);
    await reader._getCluster(0);
    await reader._getCluster(2);
    xhrCalls = [];
    await reader._getCluster(0);
    await reader._getCluster(1);

    expect(xhrCalls.map(call => call.headers.Range)).toEqual(['bytes=10-19']);
  });

  it('captures multipart support and the cap from X-Accept-Ranges-Max on init', async () => {
    respond = storage(loadMinimalZim(), { advertiseMax: 50 });
    const reader = makeReader();
    await reader.init();
    expect(reader.multipartSupported).toBe(true);
    expect(reader.maxRangesPerRequest).toBe(50);
  });

  it('leaves multipart disabled when the header is absent', async () => {
    respond = storage(loadMinimalZim());
    const reader = makeReader();
    await reader.init();
    expect(reader.multipartSupported).toBe(false);
  });

  it('fetches distinct clusters in one multi-range request and caches them', async () => {
    respond = multipartResponder();
    const reader = multiClusterReader();
    reader.multipartSupported = true;
    reader.maxRangesPerRequest = 100;

    await reader._getClusters([0, 2, 4]);

    expect(multiRangeCalls()).toHaveLength(1);
    expect(multiRangeCalls()[0].headers.Range).toBe('bytes=0-9,20-29,40-49');
    expect(reader._cache.get(0)).toBeDefined();
    expect(reader._cache.get(2)).toBeDefined();
    expect(reader._cache.get(4)).toBeDefined();
  });

  it('caches a copy, not a view pinning the whole multipart response buffer', async () => {
    respond = multipartResponder();
    const reader = multiClusterReader();
    reader.multipartSupported = true;
    reader.maxRangesPerRequest = 100;

    await reader._getClusters([0, 2, 4]);

    const cached = reader._cache.get(0);
    expect(cached.decompressed.byteLength).toBe(cached.decompressed.buffer.byteLength);
  });

  it('chunks requests to the advertised cap', async () => {
    respond = multipartResponder();
    const reader = multiClusterReader();
    reader.multipartSupported = true;
    reader.maxRangesPerRequest = 2;

    await reader._getClusters([0, 1, 2, 3]);

    expect(multiRangeCalls()).toHaveLength(2);
  });

  it('does not attempt multi-range when support was not detected', async () => {
    const reader = multiClusterReader();
    reader.multipartSupported = false;
    reader._getCluster = jest.fn(() => Promise.resolve({}));

    await reader._getClusters([0, 2]);

    expect(multiRangeCalls()).toHaveLength(0);
    expect(reader._getCluster).toHaveBeenCalledTimes(2);
  });

  it('dedupes a concurrent _getCluster against an in-flight multi-range batch', async () => {
    respond = ({ headers }) => {
      const range = headers.Range.replace('bytes=', '');
      if (range.includes(',')) {
        return multipartResponder()({ headers });
      }
      const [start, end] = range.split('-').map(Number);
      const data = new Uint8Array(end - start + 1);
      data[0] = COMPRESSION_NONE;
      return { status: 206, headers: {}, response: data.buffer };
    };
    const reader = multiClusterReader();
    reader.multipartSupported = true;
    reader.maxRangesPerRequest = 100;

    const batch = reader._getClusters([0, 1, 2]);
    const direct = reader._getCluster(1);
    await Promise.all([batch, direct]);

    expect(multiRangeCalls()).toHaveLength(1);
    expect(xhrCalls.filter(c => c.headers.Range === 'bytes=10-19')).toHaveLength(0);
    expect(await direct).toBe(reader._cache.get(1));
  });

  it('falls back to per-cluster fetches when a multi-range response is not multipart', async () => {
    respond = () => ({
      status: 200,
      headers: { 'Content-Type': 'application/octet-stream' },
      response: new ArrayBuffer(0),
    });
    const reader = multiClusterReader();
    reader.multipartSupported = true;
    reader.maxRangesPerRequest = 100;
    reader._getCluster = jest.fn(() => Promise.resolve({}));

    await reader._getClusters([0, 2, 4]);

    expect(reader._getCluster).toHaveBeenCalledTimes(3);
  });

  it('leaves no unhandled rejection when a batch fails with no concurrent waiter', async () => {
    respond = () => ({ status: 500, headers: {}, response: new ArrayBuffer(0) });
    const reader = multiClusterReader();
    reader.multipartSupported = true;
    reader.maxRangesPerRequest = 100;
    const unhandled = jest.fn();
    process.on('unhandledRejection', unhandled);
    try {
      await expect(reader._getClusters([0, 2])).rejects.toMatchObject({ name: 'ResolveError' });
      await new Promise(resolve => setTimeout(resolve, 0));
    } finally {
      process.off('unhandledRejection', unhandled);
    }
    expect(unhandled).not.toHaveBeenCalled();
  });
});
